//! Многопоточный движок перебора.
//!
//! Работа делится на батчи по индексам пространства перебора. Каждый воркер
//! атомарно берёт следующий батч — классический динамический пул: идеальная
//! балансировка, минимум оверхеда (fetch_add на батч, а не на кандидата).
//!
//! Потокобезопасные структуры:
//! - `next_batch: AtomicU64` — индекс следующего батча
//! - `attempts: AtomicU64` — счётчик попыток для статуса
//! - `stop: AtomicBool` — Ctrl+C / завершение по нахождению всех целей
//! - `found: Mutex<PotWriter>` — синхронизированный вывод+potfile

use std::collections::HashSet;
use std::io::{self, Write};
use std::path::Path;
use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
use std::sync::{Arc, Mutex};
use std::time::Instant;

use crate::attack::{combinator_candidate, straight_candidate};

display.text:
//! Многопоточный движок перебора.
//!
//! Работа делится на батчи по индексам пространства перебора. Каждый воркер
//! атомарно берёт следующий батч — классический динамический пул: идеальная
//! балансировка, минимум оверхеда (fetch_add на батч, а не на кандидата).
//!
//! Потокобезопасные структуры:
//! - `next_batch: AtomicU64` — индекс следующего батча
//! - `attempts: AtomicU64` — счётчик попыток для статуса
//! - `stop: AtomicBool` — Ctrl+C / завершение по нахождению всех целей
//! - `found: Mutex<PotWriter>` — синхронизированный вывод+potfile

use std::collections::HashSet;
use std::io::{self, Write};
use std::path::Path;
use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
use std::sync::{Arc, Mutex};
use std::time::Instant;

use crate::attack::{combinator_candidate, straight_candidate};
use crate::charset::parse_mask;
use crate::cli::{AttackMode, Config};
use crate::gpu::GpuContext;
use crate::hash::{hex_decode, hash_bytes, HashType};
use crate::potfile;

/// Сколько индексов берёт воркер за раз. Подобрано под скорость хеширования
/// на CPU: 4096 MD5 ≈ миллисекунды, атомарный контент пренебрежимо мал.
const BATCH_SIZE: u64 = 4096;
/// Размер батча для GPU-воркера: большой, чтобы оверхед dispatch + чтения
/// результатов не съедал скорость (мелкие батчи = синхронизация на каждый).
const GPU_BATCH_SIZE: u64 = 50_000_000;

/// Безопасное представление открытого текста для вывода.
/// Валидный UTF-8 — как есть; иначе hex (случай масок с ?b).
pub fn plain_to_string(bytes: &[u8]) -> String {
    match std::str::from_utf8(bytes) {
        Ok(s) => s.to_string(),
        Err(_) => {
            let mut hex = String::from("0x");
            for b in bytes {
                hex.push_str(&format!("{:02x}", b));
            }
            hex
        }
    }
}

/// Синхронизированный писатель находок: stdout (если не quiet) + potfile.
struct PotWriter {
    path: Option<std::path::PathBuf>,
    quiet: bool,
}

impl PotWriter {
    fn write_found(&mut self, hash_hex: &str, plain: &str) -> Result<(), String> {
        if !self.quiet {
            println!("{}:{}", hash_hex, plain);
        }
        if let Some(p) = &self.path {
            potfile::append_potfile(p, hash_hex, plain)?;
        }
        Ok(())
    }
}

/// Статус всего перебора: прогресс по каждому раунду (длине) отдельно.
/// Воркеры пишут в атомарные счётчики раундов, статус-тред читает.
struct StatusState {
    rounds: Vec<RoundStatus>,
}

/// Прогресс одного раунда (одной длины маски).
struct RoundStatus {
    /// Фиксированная длина раунда; 0 = не фиксирована (straight/combinator —
    /// длина берётся из текущего кандидата).
    length: usize,
    /// Всего кандидатов в раунде.
    total: u128,
    /// Сколько кандидатов раунда уже перебрано.
    attempts: AtomicU64,
    /// Текущий кандидат раунда (пароль).
    candidate: Mutex<Vec<u8>>,
}

/// Тысячный разделитель: 1234567 → "1_234_567".
fn format_thousands(n: u128) -> String {
    let s = n.to_string();
    let mut out = String::with_capacity(s.len() + s.len() / 3);
    let digits = s.len();
    for (i, c) in s.chars().enumerate() {
        if i > 0 && (digits - i) % 3 == 0 {
            out.push('_');
        }
        out.push(c);
    }
    out
}

/// Заголовок статуса: общий прогресс.
fn format_status_header(percent: f64, attempts: u64, speed: f64, elapsed_secs: f64) -> String {
    format!(
        "[*] {:.1}% | {} попыток | {} H/s | истекло {:.0} с",
        if percent.is_nan() { 0.0 } else { percent },
        format_thousands(attempts as u128),
        format_thousands(speed.round().max(0.0) as u128),
        elapsed_secs,
    )
}

/// Строка одного раунда: длина, прогресс раунда, текущий пароль.
fn format_round_line(length: usize, candidate: &[u8], percent: f64, attempts: u64) -> String {
    format!(
        "[+] длина {}: {:.1}% | {} попыток | пароль '{}'",
        length,
        if percent.is_nan() { 0.0 } else { percent },
        format_thousands(attempts as u128),
        plain_to_string(candidate),
    )
}

/// Тип источника кандидатов для движка.
enum Work {
    /// brute-force: раунды маски (для инкремента — по одной подмаске на длину).
    Mask(Vec<Vec<Vec<u8>>>),
    /// straight: строки словаря.
    Words(Vec<Vec<u8>>),
    /// combinator: пары двух словарей.
    Combo(Vec<Vec<u8>>, Vec<Vec<u8>>),
}

/// Чтение словаря: строки, обрезка \r, пропуск пустых.
fn read_wordlist(path: &Path) -> Result<Vec<Vec<u8>>, String> {
    let content = std::fs::read(path)
        .map_err(|e| format!("не удалось прочитать словарь {}: {}", path.display(), e))?;
    let mut out = Vec::new();
    for line in content.split(|&b| b == b'\n') {
        let line = line.strip_suffix(b"\r").unwrap_or(line);
        if line.is_empty() {
            continue;
        }
        out.push(line.to_vec());
    }
    Ok(out)
}

/// Чтение файла хешей. Формат строки: `hex` или `hex:метаданные` (суффикс игнорируется).
fn read_hash_file(path: &Path) -> Result<Vec<String>, String> {
    let content = std::fs::read_to_string(path)
        .map_err(|e| format!("не удалось прочитать файл хешей {}: {}", path.display(), e))?;
    let mut out = Vec::new();
    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        let hash_part = line.split(':').next().unwrap_or("").trim();
        if !hash_part.is_empty() {
            out.push(hash_part.to_string());
        }
    }
    Ok(out)
}

/// Главная точка входа крака. Возвращает число найденных.
pub fn run(cfg: &Config) -> Result<u32, String> {
    // 1. Цели.
    let mut hash_hexes: Vec<String> = cfg.hashes.clone();
    if let Some(hf) = &cfg.hash_file {
        hash_hexes.extend(read_hash_file(hf)?);
    }
    if hash_hexes.is_empty() {
        return Err("нет хешей для крака".to_string());
    }

    // Декодируем цели; ошибка hex — стоп.
    let mut targets: HashSet<Vec<u8>> = HashSet::new();
    for h in &hash_hexes {
        let raw = hex_decode(h).map_err(|e| format!("хеш '{}': {}", h, e))?;
        if raw.len() != digest_len(cfg.hash_type) {
            return Err(format!(
                "хеш '{}' имеет длину {} байт, а {} ожидает {} байт",
                h,
                raw.len(),
                cfg.hash_type.name(),
                digest_len(cfg.hash_type)
            ));
        }
        targets.insert(raw);
    }

    // 2. Potfile: не искать уже взломанное.
    if !cfg.no_potfile {
        let entries = potfile::read_potfile(&cfg.outfile)?;
        let cracked = potfile::cracked_set(&entries);
        let before = targets.len();
        targets.retain(|t| !cracked.contains(&hex_of(t)));
        let skipped = before - targets.len();
        if skipped > 0 && !cfg.quiet {
            eprintln!("[+] {} хеш(ей) уже в potfile, пропускаю", skipped);
        }
    }
    if targets.is_empty() {
        if !cfg.quiet {
            eprintln!("[*] Все хеши уже взломаны. Используйте --show для списка.");
        }
        return Ok(0);
    }

    // 3. Работа.
    let work = match cfg.attack {
        AttackMode::Straight => {
            let wl = cfg.wordlist.as_ref().expect("валидировано");
            let words = read_wordlist(wl)?;
            if words.is_empty() {
                return Err(format!("словарь {} пуст", wl.display()));
            }
            Work::Words(words)
        }
        AttackMode::Combinator => {
            let w1 = read_wordlist(cfg.wordlist.as_ref().expect("валидировано"))?;
            let w2 = read_wordlist(cfg.wordlist2.as_ref().expect("валидировано"))?;
            if w1.is_empty() || w2.is_empty() {
                return Err("один из словарей пуст".to_string());
            }
            Work::Combo(w1, w2)
        }
        AttackMode::BruteForce => {
            let mask_str = cfg.mask.as_ref().expect("валидировано");
            let customs = parse_customs(cfg)?;
            let positions = parse_mask(mask_str, &customs)?;
            if positions.is_empty() {
                return Err("маска пуста".to_string());
            }
            let rounds = if cfg.increment {
                crate::attack::mask_rounds(
                    &positions,
                    cfg.increment_min,
                    cfg.increment_max.unwrap_or(positions.len()),
                )
            } else {
                vec![positions.clone()]
            };
            Work::Mask(rounds)
        }
    };

    // 3a. GPU для атаки маской: инициализация, при неудаче — откат на CPU.
    let gpu = if cfg.attack == AttackMode::BruteForce {
        match GpuContext::new() {
            Ok(ctx) => Some(ctx),
            Err(e) => {
                if !cfg.quiet {
                    eprintln!("[!] GPU недоступен ({}), откат на CPU", e);
                }
                None
            }
        }
    } else {
        None
    };

    let threads = if gpu.is_some() {
        1 // GPU сериализует dispatch'и сам, один воркер достаточно
    } else if cfg.threads == 0 {
        std::thread::available_parallelism()
            .map(|n| n.get())
            .unwrap_or(1)
    } else {
        cfg.threads
    };

    if !cfg.quiet {
        eprintln!(
            "[*] {} | тип {} (-m {}) | атака -a {} | потоков: {}",
            cfg.hash_type.name(),
            cfg.hash_type.name(),
            cfg.hash_type.code(),
            cfg.attack.code(),
            if gpu.is_some() { "GPU".to_string() } else { threads.to_string() }
        );
    }

    // 4. Запуск воркеров.
    let start = Instant::now();
    let next_batch = Arc::new(AtomicU64::new(0));
    let attempts = Arc::new(AtomicU64::new(0));
    let stop = Arc::new(AtomicBool::new(false));
    // Сколько целей ещё не найдено: при 0 воркеры останавливаются.
    let remaining = Arc::new(AtomicU64::new(targets.len() as u64));
    let found: Arc<Mutex<PotWriter>> = Arc::new(Mutex::new(PotWriter {
        path: if cfg.no_potfile { None } else { Some(cfg.outfile.clone()) },
        quiet: cfg.quiet,
    }));

    // Работа общая для всех воркеров — клонируется один раз.
    let work_shared = Arc::new(WorkRef::new(&work));
    let total = work_shared.total();

    // Статус (-s): прогресс по каждому раунду (длине) отдельно.
    let status: Option<Arc<StatusState>> = if cfg.status && !cfg.quiet {
        let rounds = (0..work_shared.round_count())
            .map(|r| RoundStatus {
                length: work_shared.round_length(r),
                total: work_shared.round_total(r),
                attempts: AtomicU64::new(0),
                candidate: Mutex::new(Vec::new()),
            })
            .collect();
        Some(Arc::new(StatusState { rounds }))
    } else {
        None
    };

    // Ctrl+C: мягкая остановка.
    {
        let stop = Arc::clone(&stop);
        let _ = ctrlc::set_handler(move || {
            stop.store(true, Ordering::SeqCst);
        });
    }

    let results: Vec<_> = if let Some(gpu) = &gpu {
        // GPU: один воркер, цели — как Vec (для буфера таргетов).
        let targets_vec: Vec<Vec<u8>> = targets.iter().cloned().collect();
        vec![{
            let work_ref = Arc::clone(&work_shared);
            let targets_vec = Arc::new(targets_vec);
            let next_batch = Arc::clone(&next_batch);
            let attempts = Arc::clone(&attempts);
            let stop = Arc::clone(&stop);
            let remaining = Arc::clone(&remaining);
            let found = Arc::clone(&found);
            let ht = cfg.hash_type;
            let status = status.clone();
            let gpu = Arc::new(gpu.clone());
            std::thread::spawn(move || {
                worker_gpu(
                    work_ref,
                    targets_vec,
                    ht,
                    &next_batch,
                    &attempts,
                    &stop,
                    &remaining,
                    &found,
                    status.as_deref(),
                    &gpu,
                )
            })
        }]
    } else {
        (0..threads)
            .map(|_| {
                let work_ref = Arc::clone(&work_shared);
                let targets = Arc::new(targets.clone());
                let next_batch = Arc::clone(&next_batch);
                let attempts = Arc::clone(&attempts);
                let stop = Arc::clone(&stop);
                let remaining = Arc::clone(&remaining);
                let found = Arc::clone(&found);
                let ht = cfg.hash_type;
                let status = status.clone();
                std::thread::spawn(move || {
                    Ok(worker(
                        work_ref,
                        targets,
                        ht,
                        &next_batch,
                        &attempts,
                        &stop,
                        &remaining,
                        &found,
                        status.as_deref(),
                    ))
                })
            })
            .collect()
    };

    // 5. Статус-тред.
    let status_timer = cfg.status_timer;
    let status_handle = if cfg.status && !cfg.quiet {
        let next_batch = Arc::clone(&next_batch);
        let attempts = Arc::clone(&attempts);
        let stop = Arc::clone(&stop);
        let status = status.clone().expect("создано выше");
        Some(std::thread::spawn(move || {
            status_thread(next_batch, attempts, stop, total, status_timer, start, status)
        }))
    } else {
        None
    };

    // 6. Сборка.
    let mut total_found = 0u32;
    for h in results {
        match h.join() {
            Ok(Ok(n)) => total_found += n,
            Ok(Err(e)) => return Err(e),
            Err(_) => return Err("воркер упал".to_string()),
        }
    }
    // Воркеры закончили (или все цели найдены) — остановить статус-тред.
    stop.store(true, Ordering::SeqCst);
    if let Some(sh) = status_handle {
        let _ = sh.join();
    }

    let elapsed = start.elapsed();
    let att = attempts.load(Ordering::Relaxed);
    if !cfg.quiet {
        eprintln!(
            "[*] готово: {} найден(о), {} попыток за {:.1} с ({} H/s)",
            total_found,
            format_thousands(att as u128),
            elapsed.as_secs_f64(),
            format_thousands(
                if elapsed.as_secs_f64() > 0.0 {
                    (att as f64 / elapsed.as_secs_f64()).round().max(0.0)
                } else {
                    0.0
                } as u128
            ),
        );
    }
    Ok(total_found)
}

/// Вспомогательная обёртка: перечисление Work склонировано один раз в Arc,
/// воркеры читают по ссылке.
enum WorkRef {
    /// Раунды маски с прекомпутнутыми размерами раундов.
    Mask(MaskRounds),
    Words(Vec<Vec<u8>>),
    Combo(Vec<Vec<u8>>, Vec<Vec<u8>>),
}

/// Раунды маски: подмаски, их total'ы и суммарный total.
struct MaskRounds {
    rounds: Vec<Vec<Vec<u8>>>,
    totals: Vec<u128>,
    total: u128,
}

impl WorkRef {
    fn new(work: &Work) -> Self {
        match work {
            Work::Mask(rounds) => {
                let totals: Vec<u128> = rounds
                    .iter()
                    .map(|r| crate::attack::brute_total(r))
                    .collect();
                let total = totals.iter().fold(0u128, |a, b| a.saturating_add(*b));
                WorkRef::Mask(MaskRounds {
                    rounds: rounds.clone(),
                    totals,
                    total,
                })
            }
            Work::Words(w) => WorkRef::Words(w.clone()),
            Work::Combo(a, b) => WorkRef::Combo(a.clone(), b.clone()),
        }
    }

    fn total(&self) -> u128 {
        match self {
            WorkRef::Mask(m) => m.total,
            WorkRef::Words(w) => crate::attack::straight_total(w),
            WorkRef::Combo(a, b) => crate::attack::combinator_total(a, b),
        }
    }

    fn candidate(&self, mut idx: u128) -> Vec<u8> {
        match self {
            WorkRef::Mask(m) => {
                for (i, round) in m.rounds.iter().enumerate() {
                    let t = m.totals[i];
                    if idx < t {
                        return crate::charset::combo_from_index(round, idx);
                    }
                    idx -= t;
                }
                Vec::new()
            }
            WorkRef::Words(w) => straight_candidate(w, idx).to_vec(),
            WorkRef::Combo(a, b) => combinator_candidate(a, b, idx),
        }
    }

    /// Сколько раундов (длин) в работе.
    fn round_count(&self) -> usize {
        match self {
            WorkRef::Mask(m) => m.rounds.len(),
            WorkRef::Words(_) | WorkRef::Combo(..) => 1,
        }
    }

    /// Всего кандидатов в раунде `r`.
    fn round_total(&self, r: usize) -> u128 {
        match self {
            WorkRef::Mask(m) => m.totals[r],
            WorkRef::Words(w) => crate::attack::straight_total(w),
            WorkRef::Combo(a, b) => crate::attack::combinator_total(a, b),
        }
    }

    /// Эксклюзивный конец раунда `r` в глобальной нумерации индексов.
    fn round_end(&self, r: usize) -> u128 {
        match self {
            WorkRef::Mask(m) => m.totals[..=r].iter().fold(0u128, |a, b| a.saturating_add(*b)),
            WorkRef::Words(_) | WorkRef::Combo(..) => self.total(),
        }
    }

    /// Какой раунд содержит глобальный индекс `idx`.
    fn round_index(&self, idx: u128) -> usize {
        match self {
            WorkRef::Mask(m) => {
                let mut acc = 0u128;
                for (i, t) in m.totals.iter().enumerate() {
                    acc = acc.saturating_add(*t);
                    if idx < acc {
                        return i;
                    }
                }
                m.totals.len().saturating_sub(1)
            }
            _ => 0,
        }
    }

    /// Фиксированная длина раунда; 0 = не фиксирована (straight/combinator).
    fn round_length(&self, r: usize) -> usize {
        match self {
            WorkRef::Mask(m) => m.rounds[r].len(),
            _ => 0,
        }
    }
}

fn digest_len(ht: HashType) -> usize {
    match ht {
        HashType::Md5 => 16,
        HashType::Sha1 => 20,
        HashType::Sha256 => 32,
        HashType::Sha512 => 64,
    }
}

fn hex_of(raw: &[u8]) -> String {
    raw.iter().map(|b| format!("{:02x}", b)).collect()
}

fn parse_customs(cfg: &Config) -> Result<[Option<Vec<u8>>; 4], String> {
    let mut out: [Option<Vec<u8>>; 4] = [None, None, None, None];
    for (i, cs) in cfg.custom_charsets.iter().enumerate() {
        if let Some(s) = cs {
            out[i] = Some(crate::charset::parse_charset(s).map_err(|e| {
                format!("кастомный чарсет -{}: {}", i + 1, e)
            })?);
        }
    }
    Ok(out)
}

/// Тело воркера. Берёт батчи, пока есть работа; завершает работу досрочно,
/// если найдены все цели или пришёл Ctrl+C.
fn worker(
    work: Arc<WorkRef>,
    targets: Arc<HashSet<Vec<u8>>>,
    ht: HashType,
    next_batch: &AtomicU64,
    attempts: &AtomicU64,
    stop: &AtomicBool,
    remaining: &AtomicU64,
    found: &Mutex<PotWriter>,
    status: Option<&StatusState>,
) -> u32 {
    let total = work.total();
    let total_batches = if total == u128::MAX {
        u64::MAX
    } else {
        (total / BATCH_SIZE as u128) as u64 + 1
    };
    let mut local_found = 0u32;

    loop {
        if stop.load(Ordering::Relaxed) || remaining.load(Ordering::Relaxed) == 0 {
            break;
        }
        let batch = next_batch.fetch_add(1, Ordering::Relaxed);
        if batch >= total_batches {
            break;
        }
        let start_idx = (batch as u128).saturating_mul(BATCH_SIZE as u128);
        let end_idx = start_idx.saturating_add(BATCH_SIZE as u128).min(total);
        if let Some(st) = status {
            // Прогресс по раундам: батч может пересекать границу раунда.
            let mut lo = start_idx;
            while lo < end_idx {
                let r = work.round_index(lo);
                let r_end = work.round_end(r).min(end_idx);
                let cnt = (r_end - lo) as u64;
                st.rounds[r].attempts.fetch_add(cnt, Ordering::Relaxed);
                if let Ok(mut c) = st.rounds[r].candidate.lock() {
                    let cand = work.candidate(lo);
                    c.clear();
                    c.extend_from_slice(&cand);
                }
                lo = r_end;
            }
        }
        for idx in start_idx..end_idx {
            let candidate = work.candidate(idx);
            let digest = hash_bytes(ht, &candidate);
            if targets.contains(&digest) {
                let hash_hex = hex_of(&digest);
                let plain = plain_to_string(&candidate);
                if let Ok(mut w) = found.lock() {
                    let _ = w.write_found(&hash_hex, &plain);
                }
                local_found += 1;
                // Все цели найдены — просим остановиться.
                if remaining.fetch_sub(1, Ordering::Relaxed) <= 1 {
                    stop.store(true, Ordering::SeqCst);
                }
            }
        }
        attempts.fetch_add((end_idx - start_idx) as u64, Ordering::Relaxed);
    }
    local_found
}

/// Тело GPU-воркера (только маски). Берёт батчи по индексам и передаёт их
/// на видеокарту: кандидаты генерируются и хешируются в шейдере, сюда
/// возвращаются только индексы найденного (сверка — по `work.candidate`).
fn worker_gpu(
    work: Arc<WorkRef>,
    targets_vec: Arc<Vec<Vec<u8>>>,
    ht: HashType,
    next_batch: &AtomicU64,
    attempts: &AtomicU64,
    stop: &AtomicBool,
    remaining: &AtomicU64,
    found: &Mutex<PotWriter>,
    status: Option<&StatusState>,
    ctx: &GpuContext,
) -> Result<u32, String> {
    let total = work.total();
    let total_batches = if total == u128::MAX {
        u64::MAX
    } else {
        (total / GPU_BATCH_SIZE as u128) as u64 + 1
    };
    let mut local_found = 0u32;

    loop {
        if stop.load(Ordering::Relaxed) || remaining.load(Ordering::Relaxed) == 0 {
            break;
        }
        let batch = next_batch.fetch_add(1, Ordering::Relaxed);
        if batch >= total_batches {
            break;
        }
        let start_idx = (batch as u128).saturating_mul(GPU_BATCH_SIZE as u128);
        let end_idx = start_idx.saturating_add(GPU_BATCH_SIZE as u128).min(total);
        if let Some(st) = status {
            let mut lo = start_idx;
            while lo < end_idx {
                let r = work.round_index(lo);
                let r_end = work.round_end(r).min(end_idx);
                let cnt = (r_end - lo) as u64;
                st.rounds[r].attempts.fetch_add(cnt, Ordering::Relaxed);
                if let Ok(mut c) = st.rounds[r].candidate.lock() {
                    let cand = work.candidate(lo);
                    c.clear();
                    c.extend_from_slice(&cand);
                }
                lo = r_end;
            }
        }
        // Батч разбивается на сегменты по раундам: GPU работает с индексами
        // внутри раунда, движок — с глобальными.
        let mut lo = start_idx;
        while lo < end_idx {
            let r = work.round_index(lo);
            let r_start = if r == 0 { 0 } else { work.round_end(r - 1) };
            let r_end = work.round_end(r).min(end_idx);
            let work_round = match &*work {
                WorkRef::Mask(m) => &m.rounds[r],
                _ => return Err("GPU-воркер поддерживает только атаку маской".to_string()),
            };
            let found_local = ctx.crack_mask(
                ht,
                work_round,
                &targets_vec,
                (lo - r_start) as u64,
                (r_end - r_start) as u64,
            )?;
            for fl in found_local {
                let gidx = r_start + fl as u128;
                let candidate = work.candidate(gidx);
                let digest = hash_bytes(ht, &candidate);
                let hash_hex = hex_of(&digest);
                let plain = plain_to_string(&candidate);
                if let Ok(mut w) = found.lock() {
                    let _ = w.write_found(&hash_hex, &plain);
                }
                local_found += 1;
                if remaining.fetch_sub(1, Ordering::Relaxed) <= 1 {
                    stop.store(true, Ordering::SeqCst);
                }
            }
            lo = r_end;
        }
        attempts.fetch_add((end_idx - start_idx) as u64, Ordering::Relaxed);
    }
    Ok(local_found)
}

/// Статус-тред: раз в N секунд печатает в stderr блочный статус — заголовок
/// и по строке на каждый раунд (длину). Строки перерисовываются на месте
/// (каждая длина обновляется на своей строке).
fn status_thread(
    next_batch: Arc<AtomicU64>,
    attempts: Arc<AtomicU64>,
    stop: Arc<AtomicBool>,
    total: u128,
    timer_secs: u64,
    start: Instant,
    status: Arc<StatusState>,
) {
    let mut last_attempts = 0u64;
    let mut last_time = start;
    let mut printed = 0usize;
    loop {
        std::thread::sleep(std::time::Duration::from_secs(timer_secs));
        if stop.load(Ordering::Relaxed) {
            if printed > 0 {
                // Отойти от блока статуса, чтобы «готово» не прилипло к нему.
                let _ = io::stderr().write_fmt(format_args!("\n"));
                let _ = io::stderr().flush();
            }
            break;
        }
        let now_attempts = attempts.load(Ordering::Relaxed);
        let now = Instant::now();
        let dt = now.duration_since(last_time).as_secs_f64();
        let speed = if dt > 0.0 {
            (now_attempts - last_attempts) as f64 / dt
        } else {
            0.0
        };
        last_attempts = now_attempts;
        last_time = now;

        let batch = next_batch.load(Ordering::Relaxed);
        let percent = if total == u128::MAX || total == 0 {
            f64::NAN
        } else {
            let done = (batch as u128).saturating_mul(BATCH_SIZE as u128).min(total);
            done as f64 / total as f64 * 100.0
        };

        // Подняться на прошлый блок и перерисовать.
        if printed > 0 {
            let _ = io::stderr().write_fmt(format_args!("\x1b[{}A", printed));
        }
        let _ = io::stderr().write_fmt(format_args!(
            "{}\n",
            format_status_header(percent, now_attempts, speed, now.duration_since(start).as_secs_f64())
        ));
        for rs in &status.rounds {
            let att = rs.attempts.load(Ordering::Relaxed);
            let pct = if rs.total == 0 {
                f64::NAN
            } else {
                att as f64 / rs.total as f64 * 100.0
            };
            let cand = rs.candidate.lock().map(|c| c.clone()).unwrap_or_default();
            let len = if rs.length > 0 { rs.length } else { cand.len() };
            let _ = io::stderr().write_fmt(format_args!(
                "{}\n",
                format_round_line(len, &cand, pct, att)
            ));
        }
        printed = status.rounds.len() + 1;
        let _ = io::stderr().flush();
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn thousands_separator() {
        assert_eq!(format_thousands(0), "0");
        assert_eq!(format_thousands(999), "999");
        assert_eq!(format_thousands(1000), "1_000");
        assert_eq!(format_thousands(1234567), "1_234_567");
        assert_eq!(format_thousands(12345678901), "12_345_678_901");
    }

    #[test]
    fn status_header_and_round_line() {
        let h = format_status_header(45.2, 123456, 9123456.0, 4.0);
        assert!(h.contains("45.2%"));
        assert!(h.contains("123_456 попыток"));
        assert!(h.contains("9_123_456 H/s"));
        assert!(h.contains("4 с"));

        let r = format_round_line(4, b"ab12", 12.5, 1000);
        assert!(r.contains("длина 4"));
        assert!(r.contains("12.5%"));
        assert!(r.contains("1_000 попыток"));
        assert!(r.contains("пароль 'ab12'"));
    }

    #[test]
    fn round_index_and_end_for_increment_mask() {
        // Инкремент 2..4 на ?d: раунды 10, 100, 1000 комбинаций.
        let work = Work::Mask(vec![
            vec![b"0123456789".to_vec(); 2],
            vec![b"0123456789".to_vec(); 3],
            vec![b"0123456789".to_vec(); 4],
        ]);
        let wr = WorkRef::new(&work);
        assert_eq!(wr.round_count(), 3);
        assert_eq!(wr.round_length(0), 2);
        assert_eq!(wr.round_length(1), 3);
        assert_eq!(wr.round_length(2), 4);
        assert_eq!(wr.round_total(0), 100);
        assert_eq!(wr.round_total(1), 1000);
        assert_eq!(wr.round_total(2), 10000);
        assert_eq!(wr.round_end(0), 100);
        assert_eq!(wr.round_end(1), 1100);
        assert_eq!(wr.round_end(2), 11100);
        assert_eq!(wr.round_index(0), 0);
        assert_eq!(wr.round_index(99), 0);
        assert_eq!(wr.round_index(100), 1);
        assert_eq!(wr.round_index(1099), 1);
        assert_eq!(wr.round_index(1100), 2);
        assert_eq!(wr.round_index(11099), 2);
    }

    #[test]
    fn plain_to_string_utf8() {
        assert_eq!(plain_to_string(b"hello"), "hello");
    }

    #[test]
    fn plain_to_string_binary_hex() {
        let out = plain_to_string(&[0x00, 0xff, 0x41]);
        assert!(out.starts_with("0x"));
        assert!(out.contains("00ff41"));
    }

    #[test]
    fn read_wordlist_trims_cr_and_empty() {
        let p = std::env::temp_dir().join(format!("rh_wordlist_{}", std::process::id()));
        std::fs::write(&p, b"one\r\ntwo\n\nthree\n").unwrap();
        let words = read_wordlist(&p).unwrap();
        assert_eq!(words, vec![b"one".to_vec(), b"two".to_vec(), b"three".to_vec()]);
        let _ = std::fs::remove_file(&p);
    }

    #[test]
    fn read_hash_file_formats() {
        let p = std::env::temp_dir().join(format!("rh_hashes_{}", std::process::id()));
        std::fs::write(&p, "abc123\ndef456:user\n\n  ghi789  \n").unwrap();
        let hashes = read_hash_file(&p).unwrap();
        assert_eq!(hashes, vec!["abc123", "def456", "ghi789"]);
        let _ = std::fs::remove_file(&p);
    }

    #[test]
    fn hex_of_works() {
        assert_eq!(hex_of(&[0xab, 0xcd]), "abcd");
    }
}

