// WGSL: GPU-брутфорс MD5 по маске.
// Каждый инвокация обрабатывает один индекс пространства:
// генерит кандидата из индекса, хеширует MD5, сверяет с целями.
// Индексы — u64 (нужна фича SHADER_INT64): пространства ?l^8 (2e11) и
// больше не влезают в u32.

const MAX_MASK_LEN: u32 = 64u;

struct Params {
    batch_start: u32,
    batch_len: u32,
    mask_len: u32,
    num_targets: u32,
    digest_words: u32, // digest_len / 4 = 4
};

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read> charset: array<u32>;      // объединённые чарсеты по позициям
@group(0) @binding(2) var<storage, read> charset_lens: array<u32>; // [0..mask_len) длины чарсетов
@group(0) @binding(3) var<storage, read> charset_starts: array<u32>; // [0..mask_len) смещения в charset
@group(0) @binding(4) var<storage, read> targets: array<u32>;
@group(0) @binding(5) var<storage, read_write> results: array<atomic<u32>>; // [0]=счётчик пар, [1+2i]=lo, [2+2i]=hi

const RESULTS_CAPACITY: u32 = 1048576u; // пар (lo, hi)

const S: array<u32, 64> = array<u32, 64>(
    7u, 12u, 17u, 22u, 7u, 12u, 17u, 22u, 7u, 12u, 17u, 22u, 7u, 12u, 17u, 22u,
    5u, 9u, 14u, 20u, 5u, 9u, 14u, 20u, 5u, 9u, 14u, 20u, 5u, 9u, 14u, 20u,
    4u, 11u, 16u, 23u, 4u, 11u, 16u, 23u, 4u, 11u, 16u, 23u, 4u, 11u, 16u, 23u,
    6u, 10u, 15u, 21u, 6u, 10u, 15u, 21u, 6u, 10u, 15u, 21u, 6u, 10u, 15u, 21u
);

const K: array<u32, 64> = array<u32, 64>(
    0xd76aa478u, 0xe8c7b756u, 0x242070dbu, 0xc1bdceeeu,
    0xf57c0fafu, 0x4787c62au, 0xa8304613u, 0xfd469501u,
    0x698098d8u, 0x8b44f7afu, 0xffff5bb1u, 0x895cd7beu,
    0x6b901122u, 0xfd987193u, 0xa679438eu, 0x49b40821u,
    0xf61e2562u, 0xc040b340u, 0x265e5a51u, 0xe9b6c7aau,
    0xd62f105du, 0x02441453u, 0xd8a1e681u, 0xe7d3fbc8u,
    0x21e1cde6u, 0xc33707d6u, 0xf4d50d87u, 0x455a14edu,
    0xa9e3e905u, 0xfcefa3f8u, 0x676f02d9u, 0x8d2a4c8au,
    0xfffa3942u, 0x8771f681u, 0x6d9d6122u, 0xfde5380cu,
    0xa4beea44u, 0x4bdecfa9u, 0xf6bb4b60u, 0xbebfbc70u,
    0x289b7ec6u, 0xeaa127fau, 0xd4ef3085u, 0x04881d05u,
    0xd9d4d039u, 0xe6db99e5u, 0x1fa27cf8u, 0xc4ac5665u,
    0xf4292244u, 0x432aff97u, 0xab9423a7u, 0xfc93a039u,
    0x655b59c3u, 0x8f0ccc92u, 0xffeff47du, 0x85845dd1u,
    0x6fa87e4fu, 0xfe2ce6e0u, 0xa3014314u, 0x4e0811a1u,
    0xf7537e82u, 0xbd3af235u, 0x2ad7d2bbu, 0xeb86d391u
);

fn rotl(x: u32, n: u32) -> u32 {
    return (x << n) | (x >> (32u - n));
}

// MD5 одного блока (кандидат <= 55 байт). Возвращает digest: [A, B, C, D].
fn md5_block(candidate: array<u32, 16>) -> vec4u {
    var msg = candidate;
    var A: u32 = 0x67452301u;
    var B: u32 = 0xefcdab89u;
    var C: u32 = 0x98badcfeu;
    var D: u32 = 0x10325476u;

    // 4 цикла вместо одного с ветвлениями — позволяет компилятору генерировать
    // константные F/g на каждый раунд (ветвления в едином цикле не разворачиваются).
    for (var i: u32 = 0u; i < 16u; i = i + 1u) {
        let F = (B & C) | ((~B) & D);
        let g = i;
        let tmp = D;
        D = C;
        C = B;
        B = B + rotl(A + F + K[i] + msg[g], S[i]);
        A = tmp;
    }
    for (var i: u32 = 16u; i < 32u; i = i + 1u) {
        let F = (D & B) | ((~D) & C);
        let g = (5u * i + 1u) % 16u;
        let tmp = D;
        D = C;
        C = B;
        B = B + rotl(A + F + K[i] + msg[g], S[i]);
        A = tmp;
    }
    for (var i: u32 = 32u; i < 48u; i = i + 1u) {
        let F = B ^ C ^ D;
        let g = (3u * i + 5u) % 16u;
        let tmp = D;
        D = C;
        C = B;
        B = B + rotl(A + F + K[i] + msg[g], S[i]);
        A = tmp;
    }
    for (var i: u32 = 48u; i < 64u; i = i + 1u) {
        let F = C ^ (B | (~D));
        let g = (7u * i) % 16u;
        let tmp = D;
        D = C;
        C = B;
        B = B + rotl(A + F + K[i] + msg[g], S[i]);
        A = tmp;
    }
    return vec4u(A + 0x67452301u, B + 0xefcdab89u, C + 0x98badcfeu, D + 0x10325476u);
}

@compute @workgroup_size(256)
fn main(@builtin(global_invocation_id) gid: vec3u) {
    let lid: u32 = gid.x;
    if (lid >= params.batch_len) {
        return;
    }
    let idx: u32 = params.batch_start + lid;

    // 1. Кандидат из индекса (порядок как combo_from_index: старшая позиция — старший разряд).
    // Младшие разряды индекса — последние позиции маски.
    // WGSL не обнуляет локальные массивы — инициализируем явно.
    var candidate: array<u32, 16> = array<u32, 16>(
        0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u
    );
    var x: u32 = idx;
    for (var p: u32 = 0u; p < params.mask_len; p = p + 1u) {
        let pos = params.mask_len - 1u - p;
        let len: u32 = charset_lens[pos];
        let c: u32 = u32(x % len);
        x = x / len;
        let byte = charset[charset_starts[pos] + c];
        let word = pos / 4u;
        let shift = (pos % 4u) * 8u;
        candidate[word] = candidate[word] | (byte << shift);
    }

    // 2. Padding MD5: 0x80, нули, длина в битах на слове 14 (little-endian).
    let byte_len = params.mask_len;
    let word = byte_len / 4u;
    let shift = (byte_len % 4u) * 8u;
    candidate[word] = candidate[word] | (0x80u << shift);
    candidate[14u] = byte_len * 8u;
    candidate[15u] = 0u;

    // 3. Хеш.
    let d = md5_block(candidate);

    // 4. Сверка с целями (flat: num_targets * digest_words u32).
    for (var t: u32 = 0u; t < params.num_targets; t = t + 1u) {
        let base = t * params.digest_words;
        var match_all = true;
        for (var w: u32 = 0u; w < params.digest_words; w = w + 1u) {
            if (d[w] != targets[base + w]) {
                match_all = false;
                break;
            }
        }
        if (match_all) {
            let slot = atomicAdd(&results[0u], 1u);
            if (slot + 1u < RESULTS_CAPACITY) {
                atomicStore(&results[1u + slot * 2u], u32(idx));          // lo
                atomicStore(&results[2u + slot * 2u], 0u);   // hi
            }
            return;
        }
    }
}

