//! Potfile: персистентное хранилище найденных хешей.
//!
//! Формат строки (как у hashcat): `hash:plaintext`. При --show выводим
//! содержимое potfile. При краке: сначала читаем potfile (чтобы не искать
//! уже взломанное), найденное дописываем.

use std::collections::HashSet;
use std::fs::{self, OpenOptions};
use std::io::Write;
use std::path::Path;

/// Запись potfile: hex-хеш → открытый текст.
#[derive(Debug, Clone)]
pub struct PotEntry {
    pub hash_hex: String,
    pub plain: String,
}

/// Прочитать potfile. Несуществующий файл — пустой список.
pub fn read_potfile(path: &Path) -> Result<Vec<PotEntry>, String> {
    if !path.exists() {
        return Ok(Vec::new());
    }
    let content = fs::read_to_string(path)
        .map_err(|e| format!("не удалось прочитать potfile {}: {}", path.display(), e))?;
    let mut out = Vec::new();
    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        if let Some((hash, plain)) = line.split_once(':') {
            out.push(PotEntry {
                hash_hex: hash.trim().to_string(),
                plain: plain.trim().to_string(),
            });
        }
        // Строка без ':' — игнорируем (битые строки не роняем).
    }
    Ok(out)
}

/// Множество уже взломанных хешей (нижний регистр hex) — их не искать заново.
pub fn cracked_set(entries: &[PotEntry]) -> HashSet<String> {
    entries.iter().map(|e| e.hash_hex.to_lowercase()).collect()
}

/// Дописать найденное в potfile (append).
pub fn append_potfile(path: &Path, hash_hex: &str, plain: &str) -> Result<(), String> {
    let mut f = OpenOptions::new()
        .create(true)
        .append(true)
        .open(path)
        .map_err(|e| format!("не удалось открыть potfile {} на запись: {}", path.display(), e))?;
    writeln!(f, "{}:{}", hash_hex, plain)
        .map_err(|e| format!("не удалось записать potfile {}: {}", path.display(), e))
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::env::temp_dir;
    use std::sync::atomic::{AtomicU32, Ordering};

    fn tmp_path() -> std::path::PathBuf {
        static N: AtomicU32 = AtomicU32::new(0);
        let n = N.fetch_add(1, Ordering::SeqCst);
        temp_dir().join(format!("rust_hashcat_potfile_test_{}_{}", std::process::id(), n))
    }

    #[test]
    fn read_missing_returns_empty() {
        assert_eq!(read_potfile(Path::new("/nonexistent/potfile")).unwrap().len(), 0);
    }

    #[test]
    fn append_and_read_roundtrip() {
        let p = tmp_path();
        append_potfile(&p, "abc123", "password").unwrap();
        append_potfile(&p, "def456", "qwerty").unwrap();
        let entries = read_potfile(&p).unwrap();
        assert_eq!(entries.len(), 2);
        assert_eq!(entries[0].hash_hex, "abc123");
        assert_eq!(entries[0].plain, "password");
        assert_eq!(entries[1].plain, "qwerty");
        let _ = fs::remove_file(&p);
    }

    #[test]
    fn skips_malformed_lines() {
        let p = tmp_path();
        fs::write(&p, "nocolon\n\nhash:plain\n").unwrap();
        let entries = read_potfile(&p).unwrap();
        assert_eq!(entries.len(), 1);
        assert_eq!(entries[0].plain, "plain");
        let _ = fs::remove_file(&p);
    }

    #[test]
    fn cracked_set_normalizes_case() {
        let entries = vec![PotEntry {
            hash_hex: "ABC123".into(),
            plain: "x".into(),
        }];
        let set = cracked_set(&entries);
        assert!(set.contains("abc123"));
    }
}

