fn rotr64(x: u64, n: u32) -> u64 {
    return (x >> n) | (x << (64u - n));
}

// SHA-digest — big-endian слова; targets хранятся как байты digest, упакованные
// в u32 little-endian. Для сравнения разворачиваем слово.
fn swap32(x: u32) -> u32 {
    return ((x & 0xFFu) << 24u) | ((x & 0xFF00u) << 8u) | ((x >> 8u) & 0xFF00u) | ((x >> 24u) & 0xFFu);
}

// SHA512 одного блока (кандидат <= 55 байт). Возвращает digest (64 байта = 8 u64).
fn sha512_block(candidate: array<u32, 16>) -> array<u64, 8> {
    var msg: array<u64, 16> = array<u64, 16>(
        0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu
    );
    let byte_len = params.mask_len;
    for (var j: u32 = 0u; j < byte_len; j = j + 1u) {
        let b = (candidate[j / 4u] >> ((j % 4u) * 8u)) & 0xFFu;
        msg[j / 8u] = msg[j / 8u] | (u64(b) << (8u * (7u - j % 8u)));
    }
    msg[byte_len / 8u] = msg[byte_len / 8u] | (u64(0x80u) << (8u * (7u - byte_len % 8u)));
    msg[15u] = u64(byte_len) * 8lu; // длина в битах (для < 2^61 бит; старшее слово 0)

    var h: array<u64, 8> = array<u64, 8>(
        0x6a09e667f3bcc908lu, 0xbb67ae8584caa73blu, 0x3c6ef372fe94f82blu, 0xa54ff53a5f1d36f1lu,
        0x510e527fade682d1lu, 0x9b05688c2b3e6c1flu, 0x1f83d9abfb41bd6blu, 0x5be0cd19137e2179lu
    );

    var w: array<u64, 80> = array<u64, 80>(
        0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu,
        0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu,
        0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu,
        0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu,
        0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu
    );
    for (var i: u32 = 0u; i < 16u; i = i + 1u) {
        w[i] = msg[i];
    }
    for (var i: u32 = 16u; i < 80u; i = i + 1u) {
        let s0 = rotr64(w[i - 15u], 1u) ^ rotr64(w[i - 15u], 8u) ^ (w[i - 15u] >> 7u);
        let s1 = rotr64(w[i - 2u], 19u) ^ rotr64(w[i - 2u], 61u) ^ (w[i - 2u] >> 6u);
        w[i] = w[i - 16u] + s0 + w[i - 7u] + s1;
    }

    var a = h[0];
    var b = h[1];
    var c = h[2];
    var d = h[3];
    var e = h[4];
    var f = h[5];
    var g = h[6];
    var hh = h[7];

    for (var i: u32 = 0u; i < 80u; i = i + 1u) {
        let s1 = rotr64(e, 14u) ^ rotr64(e, 18u) ^ rotr64(e, 41u);
        let ch = (e & f) ^ ((~e) & g);
        let temp1 = hh + s1 + ch + K[i] + w[i];
        let s0 = rotr64(a, 28u) ^ rotr64(a, 34u) ^ rotr64(a, 39u);
        let maj = (a & b) ^ (a & c) ^ (b & c);
        let temp2 = s0 + maj;
        hh = g;
        g = f;
        f = e;
        e = d + temp1;
        d = c;
        c = b;
        b = a;
        a = temp1 + temp2;
    }

    var out: array<u64, 8> = array<u64, 8>(0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu, 0lu);
    out[0] = a + h[0];
    out[1] = b + h[1];
    out[2] = c + h[2];
    out[3] = d + h[3];
    out[4] = e + h[4];
    out[5] = f + h[5];
    out[6] = g + h[6];
    out[7] = hh + h[7];
    return out;
}

@compute @workgroup_size(256)
fn main(@builtin(global_invocation_id) gid: vec3u) {
    let lid: u32 = gid.x;
    if (lid >= params.batch_len) {
        return;
    }
    let idx: u64 = params.batch_start + u64(lid);

    var candidate: array<u32, 16> = array<u32, 16>(
        0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u
    );
    var x: u64 = idx;
    for (var p: u32 = 0u; p < params.mask_len; p = p + 1u) {
        let pos = params.mask_len - 1u - p;
        let len: u64 = u64(charset_lens[pos]);
        let c: u32 = u32(x % len);
        x = x / len;
        let byte = charset[charset_starts[pos] + c];
        let word = pos / 4u;
        let shift = (pos % 4u) * 8u;
        candidate[word] = candidate[word] | (byte << shift);
    }

    let d64 = sha512_block(candidate);

    // digest 16 u32-слов big-endian: d64[w] → 2 слова (hi, lo).
    var d: array<u32, 16> = array<u32, 16>(
        0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u
    );
    for (var w: u32 = 0u; w < 8u; w = w + 1u) {
        d[w * 2u] = swap32(u32(d64[w] >> 32u));
        d[w * 2u + 1u] = swap32(u32(d64[w]));
    }

    for (var t: u32 = 0u; t < params.num_targets; t = t + 1u) {
        let base = t * params.digest_words;
        var match_all = true;
        for (var w: u32 = 0u; w < params.digest_words; w = w + 1u) {
            if (d[w] != targets[base + w]) {
                match_all = false;
                break;
            }
        }
        if (match_all) {
            let slot = atomicAdd(&results[0u], 1u);
            if (slot + 1u < RESULTS_CAPACITY) {
                atomicStore(&results[1u + slot * 2u], u32(idx));
                atomicStore(&results[2u + slot * 2u], u32(idx >> 32u));
            }
            return;
        }
    }
}

