    // Младшие разряды индекса — последние позиции маски.
    // WGSL не обнуляет локальные массивы — инициализируем явно.
    var candidate: array<u32, 16> = array<u32, 16>(
        0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u
    );
    var x: u64 = idx;
    for (var p: u32 = 0u; p < params.mask_len; p = p + 1u) {
        let pos = params.mask_len - 1u - p;
        let len: u64 = u64(charset_lens[pos]);
        let c: u32 = u32(x % len);
        x = x / len;
        let byte = charset[charset_starts[pos] + c];
        let word = pos / 4u;
        let shift = (pos % 4u) * 8u;
        candidate[word] = candidate[word] | (byte << shift);
    }

    // 2. Padding MD5: 0x80, нули, длина в битах на слове 14 (little-endian).
    let byte_len = params.mask_len;
    let word = byte_len / 4u;
    let shift = (byte_len % 4u) * 8u;
    candidate[word] = candidate[word] | (0x80u << shift);
    candidate[14u] = byte_len * 8u;
    candidate[15u] = 0u;

    // 3. Хеш.
    let d = md5_block(candidate);

    // 4. Сверка с целями (flat: num_targets * digest_words u32).
    for (var t: u32 = 0u; t < params.num_targets; t = t + 1u) {
        let base = t * params.digest_words;
        var match_all = true;
        for (var w: u32 = 0u; w < params.digest_words; w = w + 1u) {
            if (d[w] != targets[base + w]) {
                match_all = false;
                break;
            }
        }
        if (match_all) {
            let slot = atomicAdd(&results[0u], 1u);
            if (slot + 1u < RESULTS_CAPACITY) {
                atomicStore(&results[1u + slot * 2u], u32(idx));          // lo
                atomicStore(&results[2u + slot * 2u], u32(idx >> 32u));   // hi
            }
            return;
        }
    }
}

