display.text:
fn status_thread(
    next_batch: Arc<AtomicU64>,
    attempts: Arc<AtomicU64>,
    stop: Arc<AtomicBool>,
    total: u128,
    batch_size: u64,
    timer_secs: u64,
    start: Instant,
    status: Arc<StatusState>,
) {
    let mut last_attempts = 0u64;
    let mut last_time = start;
    let mut printed = 0usize;
    loop {
        std::thread::sleep(std::time::Duration::from_secs(timer_secs));
        if stop.load(Ordering::Relaxed) {
            if printed > 0 {
                // Отойти от блока статуса, чтобы «готово» не прилипло к нему.
                let _ = io::stderr().write_fmt(format_args!("\n"));
                let _ = io::stderr().flush();
            }
            break;
        }
        let now_attempts = attempts.load(Ordering::Relaxed);
        let now = Instant::now();
        let dt = now.duration_since(last_time).as_secs_f64();
        let speed = if dt > 0.0 {
            (now_attempts - last_attempts) as f64 / dt
        } else {
            0.0
        };
        last_attempts = now_attempts;
        last_time = now;

        let batch = next_batch.load(Ordering::Relaxed);
        let percent = if total == u128::MAX || total == 0 {
            f64::NAN
        } else {
            let done = (batch as u128).saturating_mul(batch_size as u128).min(total);
            done as f64 / total as f64 * 100.0
        };

        // Подняться на прошлый блок и перерисовать.
        if printed > 0 {
            let _ = io::stderr().write_fmt(format_args!("\x1b[{}A", printed));
        }
        let _ = io::stderr().write_fmt(format_args!(
            "{}\n",
            format_status_header(percent, now_attempts, speed, now.duration_since(start).as_secs_f64())
        ));
